window.DOSIK=window.DOSIK||{};DOSIK["yc_research2"]={"2":[{"t":"tree","title":"개념적·조작적 정의","root":"**연구문제와 개념적·조작적 정의**","branches":[["목적","추상적 개념을 실증적으로 검증하기 위한 과정이다"],["이론적 배경","동일한 개념이라도 연구자의 이론적 배경에 따라 다르게 정의될 수 있다"],["속성 결정","개념의 어떤 속성을 조작할 것인가에 대하여 결정해야 한다"],["계량화","측정 가능한 형태로의 계량화가 가능하다"],["복수지표","다양한 속성의 측정을 위해 복수지표가 활용될 수 있다"]]}],"4":[{"t":"vs","title":"연구설계의 관점","cols":[{"name":"중시하는 것","items":["표본의 대표성, 관찰의 객관성, 실증주의적 관점을 중시한다","분석결과의 일반화 가능성을 중시한다"]},{"name":"결합 연구방법","items":["질적연구방법과 양적연구방법을 결합한 연구방법이다","현상에 대한 이해를 넓히고 깊이 있는 연구가 가능하다","내재된 편향이나 결함을 피하고, 타당도를 높일 수 있다","다양한 형태의 자료들을 수집하고 분석하는데 유연하다"]}]}],"5":[{"t":"tree","title":"유사실험설계","root":"**유사실험설계**","branches":[["비동질통제집단설계","비동질통제집단설계(nonequivalent control group design)는 유사실험설계에 속한다"],["피험자 배치","피험자를 무선적으로 배치하지 못한다"],["연구 상황","실험실 상황이 아닌 실제 상황에서 독립변수를 조작해 연구하는 설계이다"],["외생변수","진실험설계에 비해 외생변수의 효과를 통제하기 어렵다"]]}],"6":[{"t":"vs","title":"내적타당도와 외적타당도","cols":[{"name":"내적타당도","items":["일반적으로 실험연구는 가외변인을 통제하기 때문에 내적타당도가 높다"]},{"name":"외적타당도","items":["연구 결과를 일반화 시킬 수 있는 정도를 의미한다","무선표집(random sampling)을 실시하면 일반적으로 외적타당도가 증가한다","표본 특성이 모집단과 유사하면 외적 타당도가 높다","표본의 크기가 클수록 외적 타당도가 높다","연구 환경이 현실과 유사할수록 외적 타당도가 높다","외적타당도를 높이기 위해서는 표본의 대표성을 높여야한다","연구결과의 적용 대상, 시점, 환경의 확장과 관련이 있다","연구결과의 이용을 위해 내적타당도와 함께 고려해야 할 요소이다"]},{"name":"타당도 일반","items":["연구 수행 중에 참여자들이 이탈하고 측정도구가 바뀔 경우 연구의 타당도가 위협받는다","변인 간 상관관계를 토대로 인과관계를 단정할 수 없다"]}]}],"7":[{"t":"vs","title":"단일사례연구설계와 모의상담연구","cols":[{"name":"단일사례연구설계","items":["ABAB설계(reversal design)는 단일사례연구설계에 해당한다","ABAB설계(reversal design)와 다중기저선설계(multiple-baseline design) 등이 있다","통계적 검증보다는 임상적 유의미성을 중시한다","한 개인 또는 집단을 상대로 연구대상 내 차이를 분석하여 처치효과를 추정한다","연구를 진행하면서 연구설계나 연구절차를 유연하게 수정할 수 있다 · 연구설계나 연구절차도 융통성 있게 수정할 수 있다"]},{"name":"모의상담연구","items":["대리 내담자의 활용을 통해 재정적 부담을 완화할 수 있다","독립변수의 수준을 조작함으로써 실험 상황을 통제할 수 있다","상담과정 단순화를 통해 연구결과의 해석이 용이해진다","실험과정에서 발생할 수 있는 윤리적 문제를 회피할 수 있다"]}]}],"8":[{"t":"table","title":"표집·분석·측정·이론","head":["대상","내용"],"rows":[["표집틀의 요소들","어떤 주기적 경향성을 띠지 않아야 한다"],["군집분석","사람뿐 아니라 진술문이나 검사문항을 범주화하는 목적으로 활용된다"],["자기보고식 검사","심층면접에 비해 상대적으로 실시하기 용이하다"],["이론","인간 행동을 개념화할 뿐 아니라, 가설 도출 및 검증의 기반이 된다"],["연구자마다 다른 이론","이론을 토대로 동일한 변인을 다르게 조작적으로 정의할 수 있다"]]}],"11":[{"t":"table","title":"척도의 수준","head":["척도","특성"],"rows":[["명목척도","상호배타적 특성을 갖는다 · 측정된 표본은 한 집단에 속하면 다른 집단에 속하지 않는 상호배타적(mutually exclusive) 특성을 가지고 있다 · 점수를 토대로 이항분포 검증과 같은 통계분석이 가능하다"],["서열척도","순위에 대한 정보를 포함하고 있다"],["등간척도","측정된 점수를 토대로 표준편차 계산과 같은 통계분석이 가능하다 · 섭씨 온도는 등간(interval) 척도의 예이다"],["비율척도","절대 영점이 존재한다 · 비율(ratio) 척도는 절대 영점을 가지고 있다 · 평균과 표준편차를 구할 수 있다 · 0의 의미를 자의적으로 해석할 수 없다"],["하나의 특성","여러 가지 척도로 측정할 수 있다"]]}],"13":[{"t":"vs","title":"타당도와 신뢰도","cols":[{"name":"타당도","items":["측정하고자 하는 개념을 정확하게 측정하는 정도를 의미한다","연구의 방법 또는 절차의 결과가 실제로 의도한 목적과 일치하는 정도이다","측정과정에서 발생하는 체계적 오차와 관련이 있다","측정하고자 하는 개념에 대한 명료한 정의가 필요하다"]},{"name":"신뢰도","items":["측정하고자 하는 현상이나 대상을 일관성 있게 측정하는 정도를 의미한다","연구의 방법 또는 절차의 결과가 각각의 측정에서 일치하는 정도이다","문항들의 내용이 유사할수록 신뢰도가 증가한다","반복된 측정으로 인한 연습효과가 예상될 경우, 연구자는 동형검사(parallel forms) 사용을 고려하는 것이 좋다"]}]},{"t":"tree","title":"타당도의 평가","root":"**타당도**","branches":[["구성개념타당도","수렴타당도와 판별타당도가 있다"],["요인분석","요인분석을 통해 타당도를 평가할 수 있다"],["상호연관성","타당도와 신뢰도는 연구계획, 측정, 측정도구 사용에 있어서 상호연관성이 있을 수 있다"]]}],"15":[{"t":"vs","title":"1종 오류와 2종 오류","cols":[{"name":"1종 오류","items":["영가설이 참임에도 불구하고 이를 기각하는 오류이다","영가설을 기각했을 때 이 결정이 오류일 확률을 1종 오류라고 한다","허용범위는 유의수준이다"]},{"name":"2종 오류","items":["영가설이 거짓임에도 불구하고 이를 채택하는 오류이다"]},{"name":"통계적 검정력","items":["영가설이 참이 아닐 때 이를 기각함으로써 올바른 결정을 내릴 가능성의 정도를 통계적 검정력이라고 한다"]}]},{"t":"tree","title":"F-분포","root":"**F-분포**","branches":[["확률변수","F-분포를 따르는 확률변수는 항상 양(+)의 값을 갖는다"],["모양","분포의 모양이 자유도에 따라 달라진다"],["자유도","자유도가 커지면 정규분포에 근접한다"],["표본분산","두 개 표본분산이 사용되기 때문에 두 개 표본의 자유도가 있다"]]},{"t":"flow","title":"가설검정 절차","steps":["가설 설정은 주로 연역적 접근법을 사용한다","가설 검정을 위한 자료분석 방법은 논문의 연구방법에 기술한다","유의수준보다 유의확률(p값)이 작으면 영가설을 기각한다"]}],"18":[{"t":"tree","title":"질적연구방법","root":"**질적연구방법**","branches":[["연구 상황","자연스러운 상황에서 인간의 행동특성을 탐구한다 · 자연스러운 상황에서 수행되고 밀접한 상호작용이 자료의 원천이다"],["참여자 관점","참여자 관점에서 개인이 지각한 세계를 포착하려고 한다 · 참여자의 관점ㆍ의미 또는 참여자의 다양한 주관적 견해에 초점을 맞춘다"],["자료","상담대상과 관련된 모든 자료는 가치 있다고 간주한다 · 면접, 관찰, 문서 등 다양한 형태의 자료들을 수집한다"],["연구과정","상담과정과 연구과정을 통합하여 접근하려는 경향이 있다 · 연구설계에 있어서 초기계획이 엄격하게 규정되지 않고, 연구과정이 유연하다"]]},{"t":"tree","title":"훗설의 철학적 전통","root":"**훗설(E. Husserl)의 철학적 전통**","branches":[["이해 방식","대상 자체를 있는 그대로 이해하는 방식이다"],["선입견","대상에 대한 일체의 선입견을 배제하기 위해 노력한다"],["현상학적 환원","현상학적 환원을 통해 사물에 대한 선험적 판단을 중지할 수 있다"]]}],"19":[{"t":"table","title":"연구부정행위","head":["유형","내용"],"rows":[["위조","존재하지 않은 데이터를 허위로 만들어 내는 것"],["표절","타인의 아이디어를 정당한 승인 또는 인용 없이 활용하는 것"],["부당한 저자표시","연구에 기여하지 않은 사람에게 논문저자 자격을 부여하는 것"],["연구부정행위","이전에 출판된 자신의 연구결과를 해당 사실을 밝히지 않고 · 사용하는 것도 해당한다"]]},{"t":"tree","title":"연구 참여자 보호","root":"연구 참여자","branches":[["공정성","연구 참여자가 얻을 수 있는 이익과 · 감내해야 할 위험이 공정한지 여부를 확인한다"],["비밀 유지","연구기간 중 획득한 정보를 비밀로 유지한다"],["철회 권리","연구기간 중 연구참여를 철회할 권리가 · 있음을 알린다"],["알릴 사항","연구의 목적, 예상되는 기간 및 절차를 알린다 · 연구참여에 따른 잠재적 위험에 대해 알린다"]]}],"20":[{"t":"table","title":"연구보고서의 기술","head":["항목","기술 내용"],"rows":[["연구 결과","상담 실무 및 관련 이론에 갖는 시사점을 기술한다"],["연구가설의 지지여부","실증분석 결과를 통해 제시된다"]]}]};
