(window.TNQ=window.TNQ||[]).push({"terms":{"복수지표":{"d":"한 개념의 여러 속성을 재기 위해 함께 쓰는 둘 이상의 측정 지표.","r":[]},"유사실험설계":{"d":"실제 상황에서 독립변수를 조작하지만 피험자를 무선적으로 배치하지 못하는 설계.","r":["비동질통제집단설계","진실험설계"]},"비동질통제집단설계":{"d":"무선배치 없이 구성한 통제집단과 비교하는 유사실험설계의 한 종류.","r":["유사실험설계"]},"외생변수":{"d":"연구 목적과 무관하나 종속변수에 영향을 줄 수 있는 변수.","r":["가외변인"]},"진실험설계":{"d":"무선배치와 엄격한 통제로 외생변수 효과를 막는 실험 설계.","r":["유사실험설계"]},"가외변인":{"d":"연구하려는 변수 이외에 결과에 영향을 주는 변인.","r":["외생변수"]},"내적타당도":{"d":"결과가 독립변수의 효과 때문이라고 말할 수 있는 정도.","r":["외적타당도"]},"외적타당도":{"d":"연구 결과를 다른 대상과 상황에 일반화할 수 있는 정도.","r":["내적타당도","무선표집"]},"무선표집":{"d":"모집단에서 무작위로 표본을 뽑는 방법.","r":["외적타당도"]},"ABAB설계":{"d":"기초선과 처치 조건을 번갈아 두어 처치 효과를 확인하는 단일사례연구설계.","r":["다중기저선설계"]},"다중기저선설계":{"d":"여러 대상이나 행동에 시차를 두고 처치를 도입하는 단일사례연구설계.","r":["ABAB설계"]},"임상적 유의미성":{"d":"통계적 유의성과 달리 실제 임상에서 의미 있는 변화가 있었는지의 정도.","r":[]},"대리 내담자":{"d":"모의상담연구에서 실제 내담자 대신 역할을 맡는 사람.","r":[]},"심층면접":{"d":"깊이 있는 질문과 대화로 자료를 얻는 면접 방식.","r":[]},"상호배타적":{"d":"한 범주에 속하면 다른 범주에는 속하지 않는 관계.","r":[]},"이항분포 검증":{"d":"결과가 두 가지로 나뉘는 자료에 쓰는 통계분석.","r":[]},"절대 영점":{"d":"측정하는 특성이 전혀 없는 상태를 가리키는 0점.","r":[]},"체계적 오차":{"d":"측정에서 한쪽으로 치우쳐 일정하게 나타나는 오차.","r":["타당도"]},"신뢰도":{"d":"측정하려는 현상이나 대상을 일관성 있게 측정하는 정도.","r":["타당도"]},"타당도":{"d":"측정하려는 개념을 정확하게 측정하는 정도.","r":["신뢰도","수렴타당도"]},"동형검사":{"d":"같은 내용을 재도록 만든 서로 다른 검사로 연습효과를 피할 때 쓴다.","r":["연습효과"]},"연습효과":{"d":"같은 검사를 반복할 때 익숙해져서 결과가 달라지는 현상.","r":["동형검사"]},"수렴타당도":{"d":"같은 개념을 재는 측정치끼리 서로 높게 일치하는 정도.","r":["판별타당도"]},"판별타당도":{"d":"서로 다른 개념을 재는 측정치끼리 구별되는 정도.","r":["수렴타당도"]},"요인분석":{"d":"여러 변수를 소수의 공통 요인으로 묶는 통계 기법.","r":["타당도"]},"영가설":{"d":"차이나 효과가 없다고 설정하는 가설로 검정에서 기각 여부를 따진다.","r":["유의수준"]},"1종 오류":{"d":"참인 영가설을 기각하는 오류.","r":["영가설","통계적 검정력"]},"통계적 검정력":{"d":"영가설이 거짓일 때 이를 올바르게 기각할 가능성.","r":["영가설"]},"확률변수":{"d":"시행 결과에 따라 값이 정해지는 변수.","r":["자유도"]},"자유도":{"d":"통계량을 계산할 때 자유롭게 변할 수 있는 값의 수.","r":["표본분산"]},"표본분산":{"d":"표본의 값들이 평균에서 얼마나 흩어져 있는지를 나타내는 값.","r":["자유도"]},"연역적 접근법":{"d":"이론에서 출발해 구체적 예측을 이끌어 내는 논리.","r":[]},"유의수준":{"d":"영가설을 기각할 기준으로 연구자가 미리 정하는 확률.","r":["유의확률","영가설"]},"유의확률":{"d":"영가설이 참일 때 관찰된 결과가 나올 확률로 p값이라고도 한다.","r":["유의수준"]},"현상학적 환원":{"d":"대상에 대한 선험적 판단을 중지하고 있는 그대로 보는 절차.","r":["선험적 판단"]},"선험적 판단":{"d":"경험하기 전에 미리 가진 판단.","r":["현상학적 환원"]}},"notes":{"0의 의미를 자의적으로 해석할 수 없다":"비율척도의 0은 연구자 마음대로 정한 값이 아니라 없음을 뜻합니다.","ABAB설계(reversal design)는 단일사례연구설계에 해당한다":"ABAB설계는 한 사례를 대상으로 하는 단일사례연구설계의 한 유형입니다.","ABAB설계(reversal design)와 다중기저선설계(multiple-baseline design) 등이 있다":"단일사례연구설계에는 ABAB설계 말고도 다중기저선설계가 있습니다.","F-분포를 따르는 확률변수는 항상 양(+)의 값을 갖는다":"F-분포의 확률변수는 음수가 될 수 없고 항상 양의 값을 가집니다.","가설 검정을 위한 자료분석 방법은 논문의 연구방법에 기술한다":"가설을 어떻게 검정했는지는 논문의 연구방법 부분에 적습니다.","가설 설정은 주로 연역적 접근법을 사용한다":"가설은 이론에서 출발해 구체적 예측을 이끌어 내는 연역적 방식으로 세웁니다.","감내해야 할 위험이 공정한지 여부를 확인한다":"참여자가 감수할 위험이 이익에 비추어 공정한지 따져 보는 일입니다.","개념의 어떤 속성을 조작할 것인가에 대하여 결정해야 한다":"개념이 지닌 여러 속성 중 무엇을 측정 대상으로 삼을지 먼저 골라야 합니다.","내재된 편향이나 결함을 피하고, 타당도를 높일 수 있다":"한 방법의 약점을 다른 방법이 메워 줘서 편향을 줄이고 타당도를 높일 수 있습니다.","다양한 속성의 측정을 위해 복수지표가 활용될 수 있다":"속성이 여러 가지인 개념은 지표 하나가 아니라 여러 개로 나누어 잽니다.","다양한 형태의 자료들을 수집하고 분석하는데 유연하다":"숫자 자료와 글 자료처럼 형태가 다른 자료를 함께 모으고 분석할 수 있습니다.","대리 내담자의 활용을 통해 재정적 부담을 완화할 수 있다":"모의상담에서는 실제 내담자 대신 대리 내담자를 써서 비용 부담을 줄입니다.","대상에 대한 일체의 선입견을 배제하기 위해 노력한다":"연구자는 대상에 대한 선입견을 모두 걷어 내려고 애씁니다.","대상 자체를 있는 그대로 이해하는 방식이다":"훗설의 전통은 대상에 이론을 덧씌우지 않고 있는 그대로 이해하려는 태도입니다.","독립변수의 수준을 조작함으로써 실험 상황을 통제할 수 있다":"독립변수의 수준을 연구자가 정할 수 있어 실험 상황을 통제하기 쉽습니다.","동일한 개념이라도 연구자의 이론적 배경에 따라 다르게 정의될 수 있다":"같은 개념이어도 어떤 이론을 따르느냐에 따라 연구자마다 정의가 달라집니다.","두 개 표본분산이 사용되기 때문에 두 개 표본의 자유도가 있다":"F-분포에는 분산을 두 개 쓰므로 자유도도 두 개가 따로 붙습니다.","면접, 관찰, 문서 등 다양한 형태의 자료들을 수집한다":"질적연구는 면접과 관찰과 문서 등 여러 형태의 자료를 모읍니다.","무선표집(random sampling)을 실시하면 일반적으로 외적타당도가 증가한다":"무선표집으로 뽑으면 표본이 모집단을 대표하기 쉬워 외적타당도가 올라갑니다.","문항들의 내용이 유사할수록 신뢰도가 증가한다":"문항 내용이 비슷하면 응답이 한결같아 신뢰도가 올라갑니다.","반복된 측정으로 인한 연습효과가 예상될 경우, 연구자는 동형검사(parallel forms) 사용을 고려하는 것이 좋다":"되풀이 측정에서 연습효과가 걱정되면 같은 검사를 반복하지 않고 동형검사를 쓰는 편이 낫습니다.","변인 간 상관관계를 토대로 인과관계를 단정할 수 없다":"두 변인이 함께 변해도 그것만으로 한쪽이 원인이라고 단정할 수는 없습니다.","분석결과의 일반화 가능성을 중시한다":"이 관점은 분석 결과를 표본 밖 집단에도 적용할 수 있는지를 중시합니다.","분포의 모양이 자유도에 따라 달라진다":"F-분포는 자유도가 바뀌면 곡선 모양도 달라집니다.","비동질통제집단설계(nonequivalent control group design)는 유사실험설계에 속한다":"비동질통제집단설계는 진짜 실험설계의 조건을 다 갖추지 못한 유사실험설계의 한 종류입니다.","비율(ratio) 척도는 절대 영점을 가지고 있다":"비율척도는 특성이 전혀 없는 상태를 가리키는 절대 영점이 있는 척도입니다.","사람뿐 아니라 진술문이나 검사문항을 범주화하는 목적으로 활용된다":"군집분석은 사람은 물론 진술문과 검사문항도 비슷한 것끼리 묶는 데 씁니다.","상담과정과 연구과정을 통합하여 접근하려는 경향이 있다":"질적연구에서는 상담 진행과 연구 진행을 따로 떼지 않고 함께 다루는 경향이 있습니다.","상담과정 단순화를 통해 연구결과의 해석이 용이해진다":"상담 과정을 단순하게 만들어 놓아서 결과를 해석하기가 쉬워집니다.","상담대상과 관련된 모든 자료는 가치 있다고 간주한다":"상담 대상에 관한 자료라면 무엇이든 분석할 가치가 있다고 봅니다.","상담 실무 및 관련 이론에 갖는 시사점을 기술한다":"연구 결과가 상담 실무와 이론에 던지는 시사점을 보고서에 적습니다.","섭씨 온도는 등간(interval) 척도의 예이다":"섭씨 온도는 눈금 간격은 같지만 영점이 임의로 정해져 있어 등간척도의 예가 됩니다.","수렴타당도와 판별타당도가 있다":"구성개념타당도는 수렴타당도와 판별타당도로 나뉩니다.","순위에 대한 정보를 포함하고 있다":"서열척도는 대소의 순위는 알려 주지만 간격이 같은지는 알려 주지 않습니다.","실증분석 결과를 통해 제시된다":"연구가설이 지지되었는지는 실증분석 결과로 보여 줍니다.","실험과정에서 발생할 수 있는 윤리적 문제를 회피할 수 있다":"실제 내담자를 쓰지 않기 때문에 실험에서 생길 윤리 문제를 피할 수 있습니다.","실험실 상황이 아닌 실제 상황에서 독립변수를 조작해 연구하는 설계이다":"연구실이 아니라 실제 현장에서 독립변수를 조작해 효과를 보는 설계입니다.","심층면접에 비해 상대적으로 실시하기 용이하다":"자기보고식 검사는 심층면접보다 실시가 수월하다는 장점이 있습니다.","어떤 주기적 경향성을 띠지 않아야 한다":"표집틀의 요소는 일정한 주기로 반복되는 배열 없이 섞여 있어야 합니다.","여러 가지 척도로 측정할 수 있다":"하나의 특성도 어떻게 재느냐에 따라 여러 수준의 척도로 측정할 수 있습니다.","연구 결과를 일반화 시킬 수 있는 정도를 의미한다":"외적타당도는 연구 결과를 다른 대상과 상황에 일반화할 수 있는 정도입니다.","연구결과의 이용을 위해 내적타당도와 함께 고려해야 할 요소이다":"결과를 활용하려면 내적타당도와 더불어 외적타당도도 따져야 합니다.","연구결과의 적용 대상, 시점, 환경의 확장과 관련이 있다":"외적타당도는 결과가 어떤 사람과 시기와 장소까지 통하는지와 관련됩니다.","연구기간 중 연구참여를 철회할 권리가":"참여자가 중도에 참여를 거둬들일 수 있는 철회 권리를 보장하는 내용입니다.","연구기간 중 획득한 정보를 비밀로 유지한다":"연구하는 동안 얻은 정보는 바깥에 새지 않게 비밀로 지켜야 합니다.","연구를 진행하면서 연구설계나 연구절차를 유연하게 수정할 수 있다 · 연구설계나 연구절차도 융통성 있게 수정할 수 있다":"진행 도중 상황에 맞춰 설계와 절차를 바꿀 수 있는 융통성이 있습니다.","연구설계에 있어서 초기계획이 엄격하게 규정되지 않고, 연구과정이 유연하다":"처음 계획을 엄격히 고정하지 않아서 진행 중에 방향을 조정하기 쉽습니다.","연구 수행 중에 참여자들이 이탈하고 측정도구가 바뀔 경우 연구의 타당도가 위협받는다":"참여자가 중도에 빠지거나 도구가 달라지면 결과가 처치 때문이라고 말하기 어려워집니다.","연구에 기여하지 않은 사람에게 논문저자 자격을 부여하는 것":"기여가 없는 사람을 저자에 올리는 것도 부당한 저자표시입니다.","연구의 목적, 예상되는 기간 및 절차를 알린다":"연구 목적과 걸리는 기간, 진행 절차를 참여자에게 미리 알려 줍니다.","연구의 방법 또는 절차의 결과가 각각의 측정에서 일치하는 정도이다":"측정을 거듭해도 결과가 서로 맞아떨어지는 정도를 뜻합니다.","연구의 방법 또는 절차의 결과가 실제로 의도한 목적과 일치하는 정도이다":"방법과 절차가 낸 결과가 연구자가 의도한 목적과 맞아떨어지는 정도입니다.","연구참여에 따른 잠재적 위험에 대해 알린다":"참여하면 생길 수 있는 위험도 사전에 알려야 합니다.","연구 참여자가 얻을 수 있는 이익과":"공정성은 참여자가 얻는 이익과 짊어질 위험을 견주는 일입니다.","연구 환경이 현실과 유사할수록 외적 타당도가 높다":"연구 환경이 실제 생활과 가까울수록 결과를 현실에 옮기기 쉽습니다.","영가설을 기각했을 때 이 결정이 오류일 확률을 1종 오류라고 한다":"영가설을 기각한 결정이 틀렸을 확률을 따로 1종 오류라고 부릅니다.","영가설이 거짓임에도 불구하고 이를 채택하는 오류이다":"거짓인 영가설을 기각하지 못하고 받아들이는 오류입니다.","영가설이 참이 아닐 때 이를 기각함으로써 올바른 결정을 내릴 가능성의 정도를 통계적 검정력이라고 한다":"통계적 검정력은 영가설이 거짓일 때 이를 제대로 기각해 낼 가능성입니다.","영가설이 참임에도 불구하고 이를 기각하는 오류이다":"참인 영가설을 틀렸다고 기각해 버리는 오류에 해당합니다.","외적타당도를 높이기 위해서는 표본의 대표성을 높여야한다":"외적타당도를 높이는 길은 모집단을 잘 대표하는 표본을 확보하는 것입니다.","요인분석을 통해 타당도를 평가할 수 있다":"요인분석으로 문항이 이론이 예상한 요인으로 묶이는지 보면 타당도를 평가할 수 있습니다.","유의수준보다 유의확률(p값)이 작으면 영가설을 기각한다":"p값이 정해 둔 유의수준보다 작으면 영가설을 기각합니다.","이론을 토대로 동일한 변인을 다르게 조작적으로 정의할 수 있다":"같은 변인도 의지하는 이론이 다르면 조작적 정의가 달라질 수 있습니다.","이전에 출판된 자신의 연구결과를 해당 사실을 밝히지 않고":"이미 낸 자기 연구를 그 사실을 밝히지 않고 다시 쓰는 중복 게재가 문제 됩니다.","인간 행동을 개념화할 뿐 아니라, 가설 도출 및 검증의 기반이 된다":"이론은 행동을 개념으로 정리하는 데 그치지 않고 가설을 세우고 검증하는 토대가 됩니다.","일반적으로 실험연구는 가외변인을 통제하기 때문에 내적타당도가 높다":"실험연구는 가외변인을 막아 원인과 결과의 관계를 분명히 하므로 내적타당도가 높습니다.","자연스러운 상황에서 수행되고 밀접한 상호작용이 자료의 원천이다":"연구자와 참여자의 가까운 상호작용 자체가 자료가 되는 원천입니다.","자연스러운 상황에서 인간의 행동특성을 탐구한다":"질적연구는 꾸미지 않은 실제 상황에서 사람의 행동 특성을 살핍니다.","자유도가 커지면 정규분포에 근접한다":"자유도가 충분히 커지면 F-분포는 정규분포와 비슷해집니다.","점수를 토대로 이항분포 검증과 같은 통계분석이 가능하다":"명목척도 자료로는 이항분포 검증 같은 분석이 가능합니다.","존재하지 않은 데이터를 허위로 만들어 내는 것":"위조는 실제로 없는 데이터를 거짓으로 만들어 내는 행위입니다.","진실험설계에 비해 외생변수의 효과를 통제하기 어렵다":"무선배치와 엄격한 통제가 약해서 외생변수가 결과에 섞여 들기 쉽습니다.","질적연구방법과 양적연구방법을 결합한 연구방법이다":"혼합연구방법은 질적연구와 양적연구를 한 연구 안에서 함께 씁니다.","참여자 관점에서 개인이 지각한 세계를 포착하려고 한다":"연구자 기준이 아니라 참여자가 느낀 세계 그대로를 담아내려 합니다.","참여자의 관점ㆍ의미 또는 참여자의 다양한 주관적 견해에 초점을 맞춘다":"참여자가 부여한 의미와 서로 다른 주관적 견해에 초점을 둡니다.","추상적 개념을 실증적으로 검증하기 위한 과정이다":"조작적 정의는 눈에 보이지 않는 개념을 실제 자료로 검증할 수 있게 만드는 절차입니다.","측정 가능한 형태로의 계량화가 가능하다":"조작적 정의를 하면 개념을 숫자로 재는 것이 가능해집니다.","측정과정에서 발생하는 체계적 오차와 관련이 있다":"타당도가 낮으면 한쪽으로 치우친 체계적 오차가 측정에 섞여 있습니다.","측정된 점수를 토대로 표준편차 계산과 같은 통계분석이 가능하다":"등간척도 점수로는 표준편차를 계산하는 분석까지 할 수 있습니다.","측정된 표본은 한 집단에 속하면 다른 집단에 속하지 않는 상호배타적(mutually exclusive) 특성을 가지고 있다":"명목척도의 범주는 한 집단에 들면 다른 집단에는 들지 않는 상호배타적 성격입니다.","측정하고자 하는 개념에 대한 명료한 정의가 필요하다":"타당하게 재려면 무엇을 재는지 개념을 분명하게 정의해 두어야 합니다.","측정하고자 하는 개념을 정확하게 측정하는 정도를 의미한다":"타당도는 재려는 개념을 정확하게 재고 있는 정도입니다.","측정하고자 하는 현상이나 대상을 일관성 있게 측정하는 정도를 의미한다":"신뢰도는 같은 대상을 재면 일관된 결과가 나오는 정도입니다.","타당도와 신뢰도는 연구계획, 측정, 측정도구 사용에 있어서 상호연관성이 있을 수 있다":"타당도와 신뢰도는 연구계획부터 도구 사용까지 서로 영향을 주고받을 수 있습니다.","타인의 아이디어를 정당한 승인 또는 인용 없이 활용하는 것":"표절은 남의 아이디어를 허락이나 인용 표시 없이 가져다 쓰는 행위입니다.","통계적 검증보다는 임상적 유의미성을 중시한다":"이 설계는 통계 검증보다 임상 현장에서 의미 있는 변화가 있었는지를 봅니다.","평균과 표준편차를 구할 수 있다":"비율척도 자료로는 평균과 표준편차를 계산할 수 있습니다.","표본의 대표성, 관찰의 객관성, 실증주의적 관점을 중시한다":"양적 관점은 표본이 모집단을 대표하는지와 관찰이 객관적인지를 따집니다.","표본의 크기가 클수록 외적 타당도가 높다":"표본 수가 늘면 모집단을 더 잘 반영하게 되어 외적 타당도가 올라갑니다.","표본 특성이 모집단과 유사하면 외적 타당도가 높다":"표본이 모집단과 닮을수록 결과를 모집단에 적용하기 쉬워집니다.","피험자를 무선적으로 배치하지 못한다":"피험자를 무작위로 나누지 못하므로 집단 사이에 처음부터 차이가 남을 수 있습니다.","한 개인 또는 집단을 상대로 연구대상 내 차이를 분석하여 처치효과를 추정한다":"한 대상 안에서 처치 전후를 견주어 처치 효과를 추정합니다.","현상에 대한 이해를 넓히고 깊이 있는 연구가 가능하다":"두 방법을 합치면 현상을 폭넓게 이해하면서 깊이 있게 파고들 수 있습니다.","현상학적 환원을 통해 사물에 대한 선험적 판단을 중지할 수 있다":"현상학적 환원은 미리 가진 판단을 잠시 멈추고 대상을 보는 절차입니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
